def is_prime(n):
    """Check if a given number is prime using a for loop."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

# Get user input
num = int(input("Enter a number: "))

# Check if the number is prime
